package com.digitalbeavertz.ruqya.data

import org.json.JSONArray
import org.json.JSONObject

/**
 * Everything the app shows, read once from assets/ruqya.json. That file is generated by
 * tools/build_content.py, which takes the Quran from Tanzil and the King Fahd Complex (and
 * checks they agree) and checks every hadith text against the narration it cites.
 */

enum class Lang(val tag: String) { EN("en"), SW("sw") }

/** A text in English and Kiswahili. */
data class Txt(val en: String, val sw: String) {
    operator fun get(lang: Lang) = if (lang == Lang.SW && sw.isNotEmpty()) sw else en
}

data class Source(val book: String, val n: String, val grade: Txt?)

data class Ayah(
    val sura: Int, val aya: Int,
    /** KFGQPC Uthmanic Hafs text, ends with a no-break space and the verse number (for the Madinah font). */
    val hafs: String,
    /** Tanzil Uthmani text (for the other fonts). */
    val tanzil: String,
    val translit: String, val en: String, val sw: String,
) {
    val key get() = "$sura:$aya"
    /** everyayah.com file name, e.g. 002255. */
    val audio get() = "%03d%03d".format(sura, aya)
    /** Surahs start with the basmala, except Al-Fatihah (where it is verse 1) and At-Tawbah. */
    val startsSura get() = aya == 1 && sura != 1 && sura != 9
    fun meaning(lang: Lang) = if (lang == Lang.SW) sw else en
}

data class Passage(val id: String, val name: Txt, val ayahs: List<Ayah>) {
    /** "2:255" or "2:285-286"; passages from several surahs list them all. */
    val reference: String
        get() = ayahs.groupBy { it.sura }.entries.joinToString(", ") { (s, a) ->
            if (a.size == 1) "$s:${a[0].aya}" else "$s:${a.first().aya}-${a.last().aya}"
        }
}

data class Dua(
    val id: String, val category: String, val title: Txt,
    val ar: String, val translit: String, val meaning: Txt,
    val count: Int, val sources: List<Source>, val note: Txt?,
)

data class Action(
    val id: String, val title: Txt, val body: Txt,
    val passages: List<Passage>, val count: Int, val sources: List<Source>,
)

sealed class Step {
    abstract val count: Int
    abstract val sources: List<Source>
    abstract val note: Txt?
    abstract val title: Txt

    data class Recite(val passage: Passage, override val count: Int, override val sources: List<Source>, override val note: Txt?) : Step() {
        override val title get() = passage.name
    }
    data class Say(val dua: Dua, override val count: Int, override val sources: List<Source>, override val note: Txt?) : Step() {
        override val title get() = dua.title
    }
    data class Do(val action: Action, override val count: Int, override val sources: List<Source>, override val note: Txt?) : Step() {
        override val title get() = action.title
    }
}

data class Session(
    val id: String, val icon: String, val title: Txt, val subtitle: Txt,
    val steps: List<Step>, val isRoutine: Boolean,
)

sealed class Evidence {
    data class Quran(val passage: Passage) : Evidence()
    data class Hadith(val source: Source, val ar: String, val meaning: Txt) : Evidence()
}

data class Article(
    val id: String, val icon: String, val title: Txt,
    val bodyEn: List<String>, val bodySw: List<String>, val evidence: List<Evidence>,
) {
    fun body(lang: Lang) = if (lang == Lang.SW) bodySw else bodyEn
}

data class Category(val id: String, val title: Txt)

/** One of the 99 names, with where it comes from: a verse, a hadith, or (once) a book cited by Ibn Uthaymeen. */
data class Name(
    val number: Int, val ar: String, val translit: String, val meaning: Txt,
    val ayah: Ayah?, val hadith: Source?, val cite: Txt?, val note: Txt?,
)

class Names(
    val introEn: List<String>, val introSw: List<String>,
    /** "Allah has ninety-nine names..." (al-Bukhari). */
    val hadith: Evidence.Hadith,
    /** The narration with the well-known list, which is not authentic. */
    val weakList: Source,
    val list: List<Name>,
) {
    fun intro(lang: Lang) = if (lang == Lang.SW) introSw else introEn
}

class Content(
    val books: Map<String, Txt>,
    val passages: Map<String, Passage>,
    val duas: List<Dua>,
    val categories: List<Category>,
    val sessions: List<Session>,
    val routines: List<Session>,
    val articles: List<Article>,
    val names: Names,
    val basmalaHafs: String,
    val basmalaTanzil: String,
    val audioBase: String,
    val audioFiles: List<String>,
) {
    fun session(id: String) = (sessions + routines).firstOrNull { it.id == id }
    fun dua(id: String) = duas.firstOrNull { it.id == id }
    fun article(id: String) = articles.firstOrNull { it.id == id }

    /** "Sahih Muslim 2186" */
    fun cite(s: Source, lang: Lang) = "${books[s.book]?.get(lang) ?: s.book} ${s.n}"

    companion object {
        fun parse(json: String): Content {
            val root = JSONObject(json)
            val ayahs = root.getJSONObject("ayahs")
            fun ayah(key: String): Ayah {
                val (s, a) = key.split(":").map(String::toInt)
                val o = ayahs.getJSONObject(key)
                return Ayah(s, a, o.getString("h"), o.getString("t"), o.getString("tr"), o.getString("en"), o.getString("sw"))
            }

            fun txt(o: JSONObject?) = o?.let { Txt(it.optString("en"), it.optString("sw")) }
            fun sources(a: JSONArray?) = a.objects().map {
                Source(it.getString("book"), it.getString("n"), txt(it.optJSONObject("grade")))
            }

            val books = root.getJSONObject("books").let { b -> b.keys().asSequence().associateWith { txt(b.getJSONObject(it))!! } }

            val passages = root.getJSONArray("passages").objects().associate { p ->
                val list = p.getJSONArray("ranges").let { r ->
                    (0 until r.length()).flatMap { i ->
                        val g = r.getJSONArray(i)
                        val s = g.getInt(0)
                        (g.getInt(1)..g.getInt(2)).map { a -> ayah("$s:$a") }
                    }
                }
                p.getString("id") to Passage(p.getString("id"), txt(p.getJSONObject("name"))!!, list)
            }

            val duas = root.getJSONArray("duas").objects().map { d ->
                Dua(
                    d.getString("id"), d.getString("category"), txt(d.getJSONObject("title"))!!,
                    d.getString("ar"), d.getString("tr"), Txt(d.getString("en"), d.getString("sw")),
                    d.optInt("count", 1), sources(d.getJSONArray("src")), txt(d.optJSONObject("note")),
                )
            }.also { list -> check(list.map { it.id }.toSet().size == list.size) { "duplicate dua id" } }
            val duaById = duas.associateBy { it.id }

            val actionsJson = root.getJSONObject("actions")
            val actions = actionsJson.keys().asSequence().associateWith { id ->
                val a = actionsJson.getJSONObject(id)
                Action(
                    id, txt(a.getJSONObject("title"))!!, txt(a.getJSONObject("body"))!!,
                    a.optJSONArray("passages").strings().map { passages.getValue(it) },
                    a.optInt("count", 1), sources(a.optJSONArray("src")),
                )
            }

            fun step(o: JSONObject): Step {
                val src = o.optJSONArray("src")?.let(::sources)
                val note = txt(o.optJSONObject("note"))
                val count = if (o.has("count")) o.getInt("count") else null
                return when {
                    o.has("passage") -> Step.Recite(passages.getValue(o.getString("passage")), count ?: 1, src.orEmpty(), note)
                    o.has("dua") -> duaById.getValue(o.getString("dua")).let { d ->
                        Step.Say(d, count ?: d.count, src ?: d.sources, note ?: d.note)
                    }
                    o.has("action") -> actions.getValue(o.getString("action")).let { a ->
                        Step.Do(a, count ?: a.count, src ?: a.sources, note)
                    }
                    else -> error("step without passage, dua or action: $o")
                }
            }

            fun sessions(key: String, routine: Boolean) = root.getJSONArray(key).objects().map { s ->
                Session(
                    s.getString("id"), s.getString("icon"), txt(s.getJSONObject("title"))!!, txt(s.getJSONObject("subtitle"))!!,
                    s.getJSONArray("steps").objects().map(::step), routine,
                )
            }

            val articles = root.getJSONArray("articles").objects().map { a ->
                val body = a.getJSONObject("body")
                Article(
                    a.getString("id"), a.getString("icon"), txt(a.getJSONObject("title"))!!,
                    body.getJSONArray("en").strings(), body.getJSONArray("sw").strings(),
                    a.getJSONArray("evidence").objects().map { e ->
                        if (e.has("passage")) Evidence.Quran(passages.getValue(e.getString("passage")))
                        else Evidence.Hadith(
                            Source(e.getString("book"), e.getString("n"), txt(e.optJSONObject("grade"))),
                            e.getString("ar"), Txt(e.getString("en"), e.getString("sw")),
                        )
                    },
                )
            }

            val n = root.getJSONObject("names")
            val names = Names(
                n.getJSONObject("intro").getJSONArray("en").strings(), n.getJSONObject("intro").getJSONArray("sw").strings(),
                n.getJSONObject("intro_evidence").let { e ->
                    Evidence.Hadith(sources(JSONArray().put(e)).first(), e.getString("ar"), Txt(e.getString("en"), e.getString("sw")))
                },
                sources(JSONArray().put(n.getJSONObject("intro_weak"))).first(),
                n.getJSONArray("names").objects().mapIndexed { i, o ->
                    Name(
                        i + 1, o.getString("ar"), o.getString("tr"), Txt(o.getString("en"), o.getString("sw")),
                        o.optString("q").ifEmpty { null }?.let(::ayah),
                        o.optJSONObject("h")?.let { sources(JSONArray().put(it)).first() },
                        txt(o.optJSONObject("cite")), txt(o.optJSONObject("note")),
                    )
                },
            )

            val basmala = root.getJSONObject("basmala")
            val audio = root.getJSONObject("audio")
            return Content(
                books, passages, duas,
                root.getJSONArray("dua_categories").objects().map { Category(it.getString("id"), txt(it.getJSONObject("title"))!!) },
                sessions("sessions", false), sessions("routines", true), articles, names,
                basmala.getString("h"), basmala.getString("t"),
                audio.getString("base"), audio.getJSONArray("files").strings(),
            )
        }

        private fun JSONArray?.objects(): List<JSONObject> = if (this == null) emptyList() else (0 until length()).map { getJSONObject(it) }
        private fun JSONArray?.strings(): List<String> = if (this == null) emptyList() else (0 until length()).map { getString(it) }
    }
}
